            else if (am_wins) begin
                run_any<=1'b1; run_key<=okey(am_val);
                run_idx<=am_idx+last_row0; run_val<=am_val;
            end
        end
    end

    // DYN offsets derived once per token.
    always @(posedge clk) if (st == S_DYN) begin
        dyn[0] <= 0;
        dyn[1] <= tok_r * HID;
        dyn[2] <= pos_r * HALF;
        dyn[3] <= (pos_r >> LW) * (HD * W) + (pos_r & (W - 1));
        dyn[4] <= pos_r * HD;
        dyn[5] <= pos_r + 1;
        dyn[6] <= dyn_tiles_zero;                 // rounds of G position tiles (split 0)
        dyn[7] <= 0;
    end
    // VPOS: the eight per-position tables, same expressions at pos + o
    integer vpo;
    always @(posedge clk) if (VPOS != 0 && st == S_DYN) begin
        for (vpo = 0; vpo < 8; vpo = vpo + 1) begin
            dynp[vpo*8+0] <= 0;
            dynp[vpo*8+1] <= tok_r * HID;
            dynp[vpo*8+2] <= (pos_r + vpo[NW-1:0]) * HALF;
            dynp[vpo*8+3] <= ((pos_r + vpo[NW-1:0]) >> LW) * (HD * W) + ((pos_r + vpo[NW-1:0]) & (W - 1));
            dynp[vpo*8+4] <= (pos_r + vpo[NW-1:0]) * HD;
            dynp[vpo*8+5] <= pos_r + vpo[NW-1:0] + 1;
            dynp[vpo*8+6] <= dynp_tiles_zero[vpo];
            dynp[vpo*8+7] <= 0;
        end
    end
    `define DYNS(sel) ((VPOS != 0) ? dynp[{vp_off, sel}] : dyn[sel])


    // ---- DEC_LA (tools/qwen_rom_core_dec_emit_w12.py): predecode at push, pipelined registered tables ----
    function automatic integer la_tz(input integer value);
        integer n;
        begin
            n = 0;
            while ((value & 1) == 0 && value > 0) begin value = value >> 1; n = n + 1; end
            la_tz = n;
        end
    endfunction
    localparam integer LA_WT = la_tz(W), LA_GT = la_tz(G), LA_ODD = G >> la_tz(G);
    localparam integer LA_NO = (VPOS != 0) ? 8 : 1;         // position offsets
    localparam integer LA_SW = NW + 2;                       // rounds operand: shifted position + ODD
    localparam integer LA_H = LA_SW / 2 - 3;                 // divider split (low part: remainder + LA_H bits)
    // stage 1 (E1): pos_r + o and, for every (o, split), ((pos_r + o) >> (WT + GT - split)) + ODD
    //   (rounds = that / ODD), both through kept prefix adders
    // stage 2 (E2): high-half quotient and remainder; the other DYN entries
    // stage 3 (E3): rounds (0 for an invalid split).  The first program word reaches prog_q at E3 and is
    //   registered (pend1) at E4, when every table entry is settled.
    reg [NW-1:0]    la_po [0:LA_NO-1];
    reg [LA_SW-1:0] la_sh [0:LA_NO*16-1];
    reg [AW-1:0]    la_tokh;
    reg [LA_SW-1:0] la_qh [0:LA_NO*16-1];
    reg [LA_SW-1:0] la_lo [0:LA_NO*16-1];
    reg [AW-1:0]    la_tab [0:LA_NO*8-1];
    reg [NW-1:0]    la_rt [0:LA_NO*16-1];
    wire [15:0]  la_inv;
    wire [LA_NO*NW-1:0] la_po_n;            // packed: Yosys 0.68 asserts on an unpacked array bound to output ports
    wire [LA_NO*16*LA_SW-1:0] la_sh_n;
    genvar lap, las;
    generate for (las = 0; las < 16; las = las + 1) begin : g_la_inv
        assign la_inv[las] = (W != (1 << LA_WT)) || las > LA_GT || las > LA_WT + LA_GT;
    end endgenerate
    generate for (lap = 0; lap < LA_NO; lap = lap + 1) begin : g_la_po
        ot_hdc_ksadd_k #(.W(NW)) u_po (.a(pos_r), .b(lap), .cin(1'b0), .s(la_po_n[lap*NW +: NW]), .cout());
        for (las = 0; las < 16; las = las + 1) begin : g_s
            if (las > LA_GT || las > LA_WT + LA_GT) begin : g_inv
                assign la_sh_n[(lap*16+las)*LA_SW +: LA_SW] = {LA_SW{1'b0}};
            end else begin : g_ok
                ot_hdc_ksadd_k #(.W(LA_SW)) u_sh (.a({2'b00, (la_po_n[lap*NW +: NW] >> (LA_WT + LA_GT - las))}),
                                                 .b(LA_ODD), .cin(1'b0), .s(la_sh_n[(lap*16+las)*LA_SW +: LA_SW]), .cout());
            end
        end
    end endgenerate
    integer lo, ls;
    always @(posedge clk) if (DEC_LA != 0) begin
        la_tokh <= tok_r * HID;
        for (lo = 0; lo < LA_NO; lo = lo + 1) begin
            la_po[lo] <= la_po_n[lo*NW +: NW];
            for (ls = 0; ls < 16; ls = ls + 1)
                la_sh[lo*16+ls] <= la_sh_n[(lo*16+ls)*LA_SW +: LA_SW];
        end
        for (lo = 0; lo < LA_NO; lo = lo + 1) begin
            for (ls = 0; ls < 16; ls = ls + 1) begin
                la_qh[lo*16+ls] <= ((la_sh[lo*16+ls] >> LA_H) / LA_ODD) << LA_H;
                la_lo[lo*16+ls] <= (((la_sh[lo*16+ls] >> LA_H) % LA_ODD) << LA_H) | (la_sh[lo*16+ls] & ((1 << LA_H) - 1));
            end
            la_tab[lo*8+0] <= 0;
            la_tab[lo*8+1] <= la_tokh;
            la_tab[lo*8+2] <= la_po[lo] * HALF;
            la_tab[lo*8+3] <= (la_po[lo] >> LW) * (HD * W) + (la_po[lo] & (W - 1));
            la_tab[lo*8+4] <= la_po[lo] * HD;
            la_tab[lo*8+5] <= la_po[lo] + 1;
            la_tab[lo*8+6] <= 0;                                   // read from la_rt (split 0)
            la_tab[lo*8+7] <= 0;
        end
        for (lo = 0; lo < LA_NO * 16; lo = lo + 1)
            la_rt[lo] <= la_inv[lo % 16] ? {NW{1'b0}} : (la_qh[lo] | (la_lo[lo] / LA_ODD));
    end
    // the program word is staged one cycle (pq_r): the data fields of an entry are written one edge after its
    // push, which is no later than its LOAD edge, and they are read only after LOAD (from la_nx).  The table
    // lookups the word needs (its split rounds, its DYN values) are registered with it at pend1.
    reg [INSTR_BITS-1:0] pq_r;
    reg [2:0]     la_wr_r;
    reg           pq_v;
    wire [2:0]    pg_off = (VPOS != 0) ? prog_q[900 +: 3] : 3'd0;
    wire [6:0]    pg_rti = ((VPOS != 0) ? {pg_off, 4'd0} : 7'd0) + prog_q[O_ME_SPLIT +: 4];
    reg  [NW-1:0] pq_split_rounds;
    always @(posedge clk) if (DEC_LA != 0) begin
        pq_v <= pend1; la_wr_r <= la_wr;
        if (pend1) begin
            pq_r <= prog_q;
            pq_split_rounds <= la_rt[pg_rti];
        end
    end
    integer lq, lk;
    reg  [AW-1:0] pq_dyn_A_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_A_D <= (prog_q[O_A_D +: W_A_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_A_D +: W_A_D]];
    reg  [AW-1:0] pq_dyn_B_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_B_D <= (prog_q[O_B_D +: W_B_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_B_D +: W_B_D]];
    reg  [AW-1:0] pq_dyn_C_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_C_D <= (prog_q[O_C_D +: W_C_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_C_D +: W_C_D]];
    reg  [AW-1:0] pq_dyn_D_D;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_D_D <= (prog_q[O_D_D +: W_D_D] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_D_D +: W_D_D]];
    reg  [AW-1:0] pq_dyn_ME_D_K;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_K <= (prog_q[O_ME_D_K +: W_ME_D_K] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_ME_D_K +: W_ME_D_K]];
    reg  [AW-1:0] pq_dyn_ME_D_NOUT;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_NOUT <= (prog_q[O_ME_D_NOUT +: W_ME_D_NOUT] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_ME_D_NOUT +: W_ME_D_NOUT]];
    reg  [AW-1:0] pq_dyn_ME_D_OBASE;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_OBASE <= (prog_q[O_ME_D_OBASE +: W_ME_D_OBASE] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_ME_D_OBASE +: W_ME_D_OBASE]];
    reg  [AW-1:0] pq_dyn_ME_D_TILES;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_TILES <= (prog_q[O_ME_D_TILES +: W_ME_D_TILES] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_ME_D_TILES +: W_ME_D_TILES]];
    reg  [AW-1:0] pq_dyn_ME_D_WBASE;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_WBASE <= (prog_q[O_ME_D_WBASE +: W_ME_D_WBASE] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_ME_D_WBASE +: W_ME_D_WBASE]];
    reg  [AW-1:0] pq_dyn_ME_D_XBASE;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_ME_D_XBASE <= (prog_q[O_ME_D_XBASE +: W_ME_D_XBASE] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_ME_D_XBASE +: W_ME_D_XBASE]];
    reg  [AW-1:0] pq_dyn_SU_D_NIN;
    always @(posedge clk) if (DEC_LA != 0 && pend1)
        pq_dyn_SU_D_NIN <= (prog_q[O_SU_D_NIN +: W_SU_D_NIN] == 3'd6) ? {{(AW-NW){1'b0}}, la_rt[(VPOS != 0) ? {pg_off, 4'd0} : 7'd0]}
                                                     : la_tab[((VPOS != 0) ? {pg_off, 3'd0} : 6'd0) + prog_q[O_SU_D_NIN +: W_SU_D_NIN]];
    wire          pq_split_bad = prog_q[O_ME_D_TILES +: W_ME_D_TILES] == 3'd6 && la_inv[prog_q[O_ME_SPLIT +: 4]];
    `define FP(name) pq_r[O_``name +: W_``name]
    `define FQ(name) prog_q[O_``name +: W_``name]
    // decoded-field FIFO: 8 entries, so the entry in NEXT (la_nx) is never overwritten while it is NEXT or
    // stale-NEXT (at most 4 entries are held or in flight behind it); the fetch throttle still counts fq_n.
    reg [2:0] la_wr, la_rd, la_nx;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) begin la_wr <= 3'd0; la_rd <= 3'd0; la_nx <= 3'd0; end
        else if (st == S_IDLE) begin if (start) begin la_wr <= 3'd0; la_rd <= 3'd0; end end
        else if (st == S_RUN) begin
            if (push) la_wr <= la_wr + 1'b1;
            if (load) begin la_rd <= la_rd + 1'b1; la_nx <= la_rd; end
        end
    reg [1:0] fqd_d_unit [0:7];
    reg fqd_d_barrier [0:7];
    reg [NW-1:0] fqd_me_nout [0:7];
    reg [NW-1:0] fqd_me_tiles [0:7];
    reg [NW-1:0] fqd_me_k [0:7];
    reg fqd_me_kindk [0:7];
    reg fqd_me_wsrc [0:7];
    reg fqd_me_round [0:7];
    reg fqd_me_oen [0:7];
    reg fqd_me_amax [0:7];
    reg fqd_me_amc [0:7];
    reg [NW-1:0] fqd_me_row0 [0:7];
    reg [AW-1:0] fqd_me_wbase [0:7];
    reg [AW-1:0] fqd_me_ts [0:7];
    reg [AW-1:0] fqd_me_ks [0:7];
    reg [AW-1:0] fqd_me_js [0:7];
    reg [AW-1:0] fqd_me_xbase [0:7];
    reg [AW-1:0] fqd_me_obase [0:7];
    reg [AW-1:0] fqd_me_xks [0:7];
    reg [AW-1:0] fqd_me_xjs [0:7];
    reg [2:0] fqd_me_jsh [0:7];
    reg [AW-1:0] fqd_me_ots [0:7];
    reg [AW-1:0] fqd_me_ojs [0:7];
    reg fqd_me_mmode [0:7];
    reg fqd_d_chase [0:7];
    reg [15:0] fqd_d_chase_n [0:7];
    reg fqd_d_wait_me [0:7];
    reg fqd_d_wait_su [0:7];
    reg fqd_d_chase_rows [0:7];
    reg [3:0] fqd_me_split [0:7];
    reg [AW-1:0] fqd_me_xcs [0:7];
    reg [AW-1:0] fqd_me_wcs [0:7];
    reg fqd_me_rmax [0:7];
    reg [AW-1:0] fqd_me_mbase [0:7];
    reg [NW-1:0] fqd_su_nout [0:7];
    reg [NW-1:0] fqd_su_nin [0:7];
    reg fqd_a_src [0:7];
    reg [AW-1:0] fqd_a_base [0:7];
    reg [AW-1:0] fqd_a_so [0:7];
    reg [AW-1:0] fqd_a_si [0:7];
    reg fqd_b_src [0:7];
    reg [AW-1:0] fqd_b_base [0:7];
    reg [AW-1:0] fqd_b_so [0:7];
    reg [AW-1:0] fqd_b_si [0:7];
    reg fqd_c_src [0:7];
    reg [AW-1:0] fqd_c_base [0:7];
    reg [AW-1:0] fqd_c_so [0:7];
    reg [AW-1:0] fqd_c_si [0:7];
    reg [1:0] fqd_ma [0:7];
    reg [1:0] fqd_mb [0:7];
    reg [2:0] fqd_ad [0:7];
    reg [2:0] fqd_sfu [0:7];
    reg fqd_mc [0:7];
    reg fqd_md [0:7];
    reg [1:0] fqd_dst [0:7];
    reg [AW-1:0] fqd_d_base [0:7];
    reg [AW-1:0] fqd_d_so [0:7];
    reg [AW-1:0] fqd_d_si [0:7];
    reg [1:0] fqd_red [0:7];
    reg fqd_redsq [0:7];
    reg [AW-1:0] fqd_r_base [0:7];
    reg [AW-1:0] fqd_r_so [0:7];
    reg [31:0] fqd_imm1 [0:7];
    reg [31:0] fqd_imm2 [0:7];
    reg           fqd_bad [0:7];
    reg           fqd_kvd [0:7];
    reg           fqd_wd  [0:7];
    wire [NW-1:0] pa_me_nout;
    ot_hdc_ksadd_k #(.W(NW)) u_pa_me_nout (.a(`FP(ME_NOUT)), .b(pq_dyn_ME_D_NOUT), .cin(1'b0), .s(pa_me_nout), .cout());
    wire [NW-1:0] pa_me_tiles;
    ot_hdc_ksadd_k #(.W(NW)) u_pa_me_tiles (.a(`FP(ME_TILES)), .b(((`FP(ME_D_TILES) == 3'd6) ? pq_split_rounds : pq_dyn_ME_D_TILES)), .cin(1'b0), .s(pa_me_tiles), .cout());
    wire [NW-1:0] pa_me_k;
    ot_hdc_ksadd_k #(.W(NW)) u_pa_me_k (.a(`FP(ME_K)), .b(pq_dyn_ME_D_K), .cin(1'b0), .s(pa_me_k), .cout());
    wire [AW-1:0] pa_me_wbase;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_me_wbase (.a(`FP(ME_WBASE)), .b(pq_dyn_ME_D_WBASE), .cin(1'b0), .s(pa_me_wbase), .cout());
    wire [AW-1:0] pa_me_xbase;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_me_xbase (.a(`FP(ME_XBASE)), .b(pq_dyn_ME_D_XBASE), .cin(1'b0), .s(pa_me_xbase), .cout());
    wire [AW-1:0] pa_me_obase;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_me_obase (.a(`FP(ME_OBASE)), .b(pq_dyn_ME_D_OBASE), .cin(1'b0), .s(pa_me_obase), .cout());
    wire [NW-1:0] pa_su_nin;
    ot_hdc_ksadd_k #(.W(NW)) u_pa_su_nin (.a(`FP(SU_NIN)), .b(pq_dyn_SU_D_NIN), .cin(1'b0), .s(pa_su_nin), .cout());
    wire [AW-1:0] pa_a_base;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_a_base (.a(`FP(A_BASE)), .b(pq_dyn_A_D), .cin(1'b0), .s(pa_a_base), .cout());
    wire [AW-1:0] pa_b_base;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_b_base (.a(`FP(B_BASE)), .b(pq_dyn_B_D), .cin(1'b0), .s(pa_b_base), .cout());
    wire [AW-1:0] pa_c_base;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_c_base (.a(`FP(C_BASE)), .b(pq_dyn_C_D), .cin(1'b0), .s(pa_c_base), .cout());
    wire [AW-1:0] pa_d_base;
    ot_hdc_ksadd_k #(.W(AW)) u_pa_d_base (.a(`FP(D_BASE)), .b(pq_dyn_D_D), .cin(1'b0), .s(pa_d_base), .cout());
    // data fields from the staged word; control fields (below) from prog_q at pend1.  Written on pend1 (pq_v) alone:
    // outside S_RUN the slot la_wr is free (never NEXT, never held), so such a write is dead
    always @(posedge clk) if (DEC_LA != 0 && pq_v) begin
            fqd_me_nout[la_wr_r] <= pa_me_nout;
            fqd_me_tiles[la_wr_r] <= pa_me_tiles;
            fqd_me_k[la_wr_r] <= pa_me_k;
            fqd_me_kindk[la_wr_r] <= (`FP(ME_D_TILES) == 3'd6);
            fqd_me_round[la_wr_r] <= `FP(ME_ROUND);
            fqd_me_oen[la_wr_r] <= `FP(ME_OEN);
            fqd_me_amax[la_wr_r] <= `FP(ME_AMAX);
            fqd_me_amc[la_wr_r] <= `FP(ME_AMC);
            fqd_me_row0[la_wr_r] <= `FP(ME_ROW0) | ((QWEN_FULLSHAPE != 0) ? ({{(NW-2){1'b0}}, pq_r[O_ME_ROW0+W_ME_ROW0+W_ME_AMC +: 2]} << 16) : '0);
            fqd_me_wbase[la_wr_r] <= pa_me_wbase;
            fqd_me_ts[la_wr_r] <= `FP(ME_TS);
            fqd_me_ks[la_wr_r] <= `FP(ME_KS);
            fqd_me_js[la_wr_r] <= `FP(ME_JS);
            fqd_me_xbase[la_wr_r] <= pa_me_xbase;
            fqd_me_obase[la_wr_r] <= pa_me_obase;
            fqd_me_xks[la_wr_r] <= `FP(ME_XKS);
            fqd_me_xjs[la_wr_r] <= `FP(ME_XJS);
            fqd_me_jsh[la_wr_r] <= `FP(ME_JSH);
            fqd_me_ots[la_wr_r] <= `FP(ME_OTS);
            fqd_me_ojs[la_wr_r] <= `FP(ME_OJS);
            fqd_me_mmode[la_wr_r] <= `FP(ME_MMODE);
            fqd_me_split[la_wr_r] <= `FP(ME_SPLIT);
            fqd_me_xcs[la_wr_r] <= `FP(ME_XCS);
            fqd_me_wcs[la_wr_r] <= `FP(ME_WCS);
            fqd_me_rmax[la_wr_r] <= `FP(ME_RMAX);
            fqd_me_mbase[la_wr_r] <= `FP(ME_MBASE);
            fqd_su_nout[la_wr_r] <= `FP(SU_NOUT);
            fqd_su_nin[la_wr_r] <= pa_su_nin;
            fqd_a_base[la_wr_r] <= pa_a_base;
            fqd_a_so[la_wr_r] <= `FP(A_SO);
            fqd_a_si[la_wr_r] <= `FP(A_SI);
            fqd_b_src[la_wr_r] <= `FP(B_SRC);
            fqd_b_base[la_wr_r] <= pa_b_base;
            fqd_b_so[la_wr_r] <= `FP(B_SO);
            fqd_b_si[la_wr_r] <= `FP(B_SI);
            fqd_c_src[la_wr_r] <= `FP(C_SRC);
            fqd_c_base[la_wr_r] <= pa_c_base;
            fqd_c_so[la_wr_r] <= `FP(C_SO);
            fqd_c_si[la_wr_r] <= `FP(C_SI);
            fqd_ma[la_wr_r] <= `FP(MA);
            fqd_mb[la_wr_r] <= `FP(MB);
            fqd_ad[la_wr_r] <= `FP(AD);
            fqd_sfu[la_wr_r] <= `FP(SFU);
            fqd_mc[la_wr_r] <= `FP(MC);
            fqd_md[la_wr_r] <= `FP(MD);
            fqd_dst[la_wr_r] <= `FP(DST);
            fqd_d_base[la_wr_r] <= pa_d_base;
            fqd_d_so[la_wr_r] <= `FP(D_SO);
            fqd_d_si[la_wr_r] <= `FP(D_SI);
            fqd_red[la_wr_r] <= `FP(RED);
            fqd_redsq[la_wr_r] <= `FP(RED_SQ);
            fqd_r_base[la_wr_r] <= `FP(R_BASE);
            fqd_r_so[la_wr_r] <= `FP(R_SO);
            fqd_imm1[la_wr_r] <= `FP(IMM1);
            fqd_imm2[la_wr_r] <= `FP(IMM2);
    end
    always @(posedge clk) if (DEC_LA != 0 && pend1) begin
            fqd_d_unit[la_wr] <= `FQ(UNIT);
            fqd_d_barrier[la_wr] <= `FQ(BARRIER);
            fqd_me_wsrc[la_wr] <= `FQ(ME_WSRC);
            fqd_d_chase[la_wr] <= `FQ(CHASE);
            fqd_d_chase_n[la_wr] <= `FQ(CHASE_N);
            fqd_d_wait_me[la_wr] <= `FQ(WAIT_ME);
            fqd_d_wait_su[la_wr] <= `FQ(WAIT_SU);
            fqd_d_chase_rows[la_wr] <= `FQ(CHASE_ROWS);
            fqd_a_src[la_wr] <= `FQ(A_SRC);
            fqd_bad[la_wr] <= pq_split_bad;
            fqd_kvd[la_wr] <= prog_q[O_UNIT +: W_UNIT] == 2'd1 && prog_q[O_ME_WSRC];
            fqd_wd[la_wr]  <= (W_HBM != 0) && prog_q[O_UNIT +: W_UNIT] == 2'd1 && !prog_q[O_ME_WSRC];
    end
    `undef FP
    `undef FQ
    // NEXT: control fields are registers (issue reads them); data fields are the NEXT entry of the FIFO
    assign me_nout = (DEC_LA != 0) ? fqd_me_nout[la_nx] : me_nout_q;
    assign me_tiles = (DEC_LA != 0) ? fqd_me_tiles[la_nx] : me_tiles_q;
    assign me_k = (DEC_LA != 0) ? fqd_me_k[la_nx] : me_k_q;
    assign me_kindk = (DEC_LA != 0) ? fqd_me_kindk[la_nx] : me_kindk_q;
    assign me_round = (DEC_LA != 0) ? fqd_me_round[la_nx] : me_round_q;
    assign me_oen = (DEC_LA != 0) ? fqd_me_oen[la_nx] : me_oen_q;
    assign me_amax = (DEC_LA != 0) ? fqd_me_amax[la_nx] : me_amax_q;
    assign me_amc = (DEC_LA != 0) ? fqd_me_amc[la_nx] : me_amc_q;
    assign me_row0 = (DEC_LA != 0) ? fqd_me_row0[la_nx] : me_row0_q;
    assign me_wbase = (DEC_LA != 0) ? fqd_me_wbase[la_nx] : me_wbase_q;
    assign me_ts = (DEC_LA != 0) ? fqd_me_ts[la_nx] : me_ts_q;
    assign me_ks = (DEC_LA != 0) ? fqd_me_ks[la_nx] : me_ks_q;
    assign me_js = (DEC_LA != 0) ? fqd_me_js[la_nx] : me_js_q;
    assign me_xbase = (DEC_LA != 0) ? fqd_me_xbase[la_nx] : me_xbase_q;
    assign me_obase = (DEC_LA != 0) ? fqd_me_obase[la_nx] : me_obase_q;
    assign me_xks = (DEC_LA != 0) ? fqd_me_xks[la_nx] : me_xks_q;
    assign me_xjs = (DEC_LA != 0) ? fqd_me_xjs[la_nx] : me_xjs_q;
    assign me_jsh = (DEC_LA != 0) ? fqd_me_jsh[la_nx] : me_jsh_q;
    assign me_ots = (DEC_LA != 0) ? fqd_me_ots[la_nx] : me_ots_q;
    assign me_ojs = (DEC_LA != 0) ? fqd_me_ojs[la_nx] : me_ojs_q;
    assign me_mmode = (DEC_LA != 0) ? fqd_me_mmode[la_nx] : me_mmode_q;
    assign me_split = (DEC_LA != 0) ? fqd_me_split[la_nx] : me_split_q;
    assign me_xcs = (DEC_LA != 0) ? fqd_me_xcs[la_nx] : me_xcs_q;
    assign me_wcs = (DEC_LA != 0) ? fqd_me_wcs[la_nx] : me_wcs_q;
    assign me_rmax = (DEC_LA != 0) ? fqd_me_rmax[la_nx] : me_rmax_q;
    assign me_mbase = (DEC_LA != 0) ? fqd_me_mbase[la_nx] : me_mbase_q;
    assign su_nout = (DEC_LA != 0) ? fqd_su_nout[la_nx] : su_nout_q;
    assign su_nin = (DEC_LA != 0) ? fqd_su_nin[la_nx] : su_nin_q;
    assign a_base = (DEC_LA != 0) ? fqd_a_base[la_nx] : a_base_q;
    assign a_so = (DEC_LA != 0) ? fqd_a_so[la_nx] : a_so_q;
    assign a_si = (DEC_LA != 0) ? fqd_a_si[la_nx] : a_si_q;
    assign b_src = (DEC_LA != 0) ? fqd_b_src[la_nx] : b_src_q;
    assign b_base = (DEC_LA != 0) ? fqd_b_base[la_nx] : b_base_q;
    assign b_so = (DEC_LA != 0) ? fqd_b_so[la_nx] : b_so_q;
    assign b_si = (DEC_LA != 0) ? fqd_b_si[la_nx] : b_si_q;
    assign c_src = (DEC_LA != 0) ? fqd_c_src[la_nx] : c_src_q;
    assign c_base = (DEC_LA != 0) ? fqd_c_base[la_nx] : c_base_q;
    assign c_so = (DEC_LA != 0) ? fqd_c_so[la_nx] : c_so_q;
    assign c_si = (DEC_LA != 0) ? fqd_c_si[la_nx] : c_si_q;
    assign ma = (DEC_LA != 0) ? fqd_ma[la_nx] : ma_q;
    assign mb = (DEC_LA != 0) ? fqd_mb[la_nx] : mb_q;
    assign ad = (DEC_LA != 0) ? fqd_ad[la_nx] : ad_q;
    assign sfu = (DEC_LA != 0) ? fqd_sfu[la_nx] : sfu_q;
    assign mc = (DEC_LA != 0) ? fqd_mc[la_nx] : mc_q;
    assign md = (DEC_LA != 0) ? fqd_md[la_nx] : md_q;
    assign dst = (DEC_LA != 0) ? fqd_dst[la_nx] : dst_q;
    assign d_base = (DEC_LA != 0) ? fqd_d_base[la_nx] : d_base_q;
    assign d_so = (DEC_LA != 0) ? fqd_d_so[la_nx] : d_so_q;
    assign d_si = (DEC_LA != 0) ? fqd_d_si[la_nx] : d_si_q;
    assign red = (DEC_LA != 0) ? fqd_red[la_nx] : red_q;
    assign redsq = (DEC_LA != 0) ? fqd_redsq[la_nx] : redsq_q;
    assign r_base = (DEC_LA != 0) ? fqd_r_base[la_nx] : r_base_q;
    assign r_so = (DEC_LA != 0) ? fqd_r_so[la_nx] : r_so_q;
    assign imm1 = (DEC_LA != 0) ? fqd_imm1[la_nx] : imm1_q;
    assign imm2 = (DEC_LA != 0) ? fqd_imm2[la_nx] : imm2_q;
    // Decode: every base and count may add one DYN value.
    always @(posedge clk) if (load) begin
        if (DEC_LA != 0) begin
            d_unit <= fqd_d_unit[la_rd];
            d_barrier <= fqd_d_barrier[la_rd];
            me_wsrc <= fqd_me_wsrc[la_rd];
            d_chase <= fqd_d_chase[la_rd];
            d_chase_n <= fqd_d_chase_n[la_rd];
            d_wait_me <= fqd_d_wait_me[la_rd];
            d_wait_su <= fqd_d_wait_su[la_rd];
            d_chase_rows <= fqd_d_chase_rows[la_rd];
            a_src <= fqd_a_src[la_rd];
        end else begin
        d_unit <= `F(UNIT); d_barrier <= `F(BARRIER);
        me_nout_q <= `F(ME_NOUT) + `DYNS(`F(ME_D_NOUT));
        //: DYN_TTILES counts exact rounds of G/S position tiles (S = 2^split)
        me_tiles_q <= `F(ME_TILES) + ((`F(ME_D_TILES) == 3'd6) ? dyn_tiles_split
                                                               : `DYNS(`F(ME_D_TILES)));
        me_k_q <= `F(ME_K) + `DYNS(`F(ME_D_K));
        me_kindk_q <= (`F(ME_D_TILES) == 3'd6);        // DYN_TTILES: rounds of position tiles
        me_wsrc <= `F(ME_WSRC); me_round_q <= `F(ME_ROUND); me_oen_q <= `F(ME_OEN); me_amax_q <= `F(ME_AMAX);
        me_amc_q <= `F(ME_AMC);
        me_row0_q <= `F(ME_ROW0) |
                   ((QWEN_FULLSHAPE != 0) ?
                    ({{(NW-2){1'b0}}, ir[O_ME_ROW0+W_ME_ROW0+W_ME_AMC +: 2]} << 16) : '0);
        me_wbase_q <= `F(ME_WBASE) + `DYNS(`F(ME_D_WBASE));
        me_ts_q <= `F(ME_TS); me_ks_q <= `F(ME_KS); me_js_q <= `F(ME_JS);
        me_xbase_q <= `F(ME_XBASE) + `DYNS(`F(ME_D_XBASE));
        me_obase_q <= `F(ME_OBASE) + `DYNS(`F(ME_D_OBASE));
        me_xks_q <= `F(ME_XKS); me_xjs_q <= `F(ME_XJS); me_jsh_q <= `F(ME_JSH);
        me_ots_q <= `F(ME_OTS); me_ojs_q <= `F(ME_OJS); me_mmode_q <= `F(ME_MMODE);
        d_chase <= `F(CHASE); d_chase_n <= `F(CHASE_N); d_wait_me <= `F(WAIT_ME); d_wait_su <= `F(WAIT_SU);
        d_chase_rows <= `F(CHASE_ROWS);
        me_split_q <= `F(ME_SPLIT); me_xcs_q <= `F(ME_XCS); me_wcs_q <= `F(ME_WCS);
        me_rmax_q <= `F(ME_RMAX); me_mbase_q <= `F(ME_MBASE);
        su_nout_q <= `F(SU_NOUT);
        su_nin_q <= `F(SU_NIN) + `DYNS(`F(SU_D_NIN));
        a_src <= `F(A_SRC); a_base_q <= `F(A_BASE) + `DYNS(`F(A_D)); a_so_q <= `F(A_SO); a_si_q <= `F(A_SI);
        b_src_q <= `F(B_SRC); b_base_q <= `F(B_BASE) + `DYNS(`F(B_D)); b_so_q <= `F(B_SO); b_si_q <= `F(B_SI);
        c_src_q <= `F(C_SRC); c_base_q <= `F(C_BASE) + `DYNS(`F(C_D)); c_so_q <= `F(C_SO); c_si_q <= `F(C_SI);
        ma_q <= `F(MA); mb_q <= `F(MB); ad_q <= `F(AD); sfu_q <= `F(SFU); mc_q <= `F(MC); md_q <= `F(MD);
        dst_q <= `F(DST); d_base_q <= `F(D_BASE) + `DYNS(`F(D_D)); d_so_q <= `F(D_SO); d_si_q <= `F(D_SI);
        red_q <= `F(RED); redsq_q <= `F(RED_SQ); r_base_q <= `F(R_BASE); r_so_q <= `F(R_SO);
        imm1_q <= `F(IMM1); imm2_q <= `F(IMM2);
        end
    end
    `undef F

    // -- units ----------------------------------------------------------------------
    wire me_wrom_re, su_wrom_re;
    wire [AW-1:0] me_wrom_addr, su_wrom_addr;
    wire [SW-1:0] su_va_re;
    wire [SW*AW-1:0] su_va_addr;
    wire [SW*32-1:0] su_va_q;
    reg embed_active, embed_scale_pending;
    reg [15:0] embed_scale_hold;
    reg [SW-1:0] embed_sel;
    reg [SW*$clog2(EMB_CODE_LANES)-1:0] embed_lanes;
    wire [SW-1:0] embed_faults;
    assign embed_scale_re = (INT8_EMBED != 0) && start && st == S_IDLE;
    assign embed_scale_addr = token;
    assign embed_code_re = (INT8_EMBED != 0) && (|(su_va_re & {SW{embed_active}}));
    // The stream's element address is AW bits; token*HID wraps for vocab
    // rows >= 2^(AW-log2(HID)). Recover the in-row offset from those low
    // bits, then form the code-word address from the full NW-bit token.
    assign embed_code_addr = (QWEN_FULLSHAPE != 0) ?
        ((tok_r * (HID / EMB_CODE_LANES)) +
         (((su_va_addr[0 +: AW] - EMB_ADDR_BASE) & (HID - 1)) /
          EMB_CODE_LANES)) :
        ((su_va_addr[0 +: AW] - EMB_ADDR_BASE) >> $clog2(EMB_CODE_LANES));
    assign va_re = su_va_re & ~({SW{(INT8_EMBED != 0) && embed_active}});
    assign va_addr = su_va_addr;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            embed_active <= 1'b0;
            embed_scale_pending <= 1'b0;
            embed_sel <= 0;
        end else begin
            if (su_go) embed_active <= (INT8_EMBED != 0) && a_src;
            embed_scale_pending <= embed_scale_re;
            embed_sel <= su_va_re & {SW{(INT8_EMBED != 0) && embed_active}};
        end
    end
    always @(posedge clk) begin
        if (embed_scale_pending) embed_scale_hold <= embed_scale_q;
    end
    genvar el;
    generate if (INT8_EMBED != 0) begin : g_int8_embed
    for (el = 0; el < SW; el = el + 1) begin : g_embed_decode
        localparam integer ELI = $clog2(EMB_CODE_LANES);
        always @(posedge clk) embed_lanes[el*ELI +: ELI] <= su_va_addr[el*AW +: ELI];
        wire [31:0] decoded;
        wire bad;
        ot_hdc_qwen_int8_embed_decode u_decode (
            .code(embed_code_q[8*embed_lanes[el*ELI +: ELI] +: 8]),
            .scale(embed_scale_hold), .value(decoded), .fault(bad));
        assign su_va_q[el*32 +: 32] = embed_sel[el] ? decoded : va_q[el*32 +: 32];
        assign embed_faults[el] = embed_sel[el] && bad;
    end
    end else begin : g_plain_embed
        assign su_va_q = va_q;
        assign embed_faults = 0;
    end endgenerate
    // -- engine clock enable (ME_STALL) ------------------------------------------
    //: rst_n forces the enable so the gated registers see reset edges (see
    //: ot_hdc_cg).  The enable is combinational from the supply's view of the
    //: engine's registered requests; it never depends on me_go.
    wire me_wake = (st == S_RUN) && nx_v && (d_unit == 2'd1);
    assign me_en = !rst_n || (((ME_STALL == 0) || me_mem_ok) &&
                              ((ME_IDLE_GATE == 0) || !me_idle || me_wake));
    assign me_clk_en = me_en;
    wire me_clk;
    generate if (ME_STALL != 0 || ME_IDLE_GATE != 0) begin : g_me_cg
        ot_hdc_cg u_me_cg (.clk(clk), .en(me_en), .gclk(me_clk));
    end else begin : g_me_clk
        assign me_clk = clk;
    end endgenerate
    wire [(G >> SMIN)-1:0] me_o_we;
    wire         me_mx_we;
    //: a held engine keeps its write strobes high; write once per engine edge
    assign vw_me_we = me_o_we & {(G >> SMIN){me_en}};
    assign vw_mx_we = me_mx_we & me_en;
    ot_qwen_me_spine_w12 #(.W(W), .IL(IL), .AW(AW), .NW(NW), .INT8_SCALE_WCS_BASE(INT8_SCALE_WCS_BASE),
                    .GT(G), .TG(4), .SMIN(SMIN), .SMAX(SMAX), .TCUT(TCUT), .BD(BD), .XVM(XVM), .NWS(NWS), .TWS(TWS), .ORD(ORD), .SCALE_LOCAL(SCALE_LOCAL), .MEM_EXTRA(MEM_EXTRA), .ACC_LAT(ACC_LAT), .TREE_LAT(TREE_LAT), .MUL_LAT(MUL_LAT), .FAST_ISSUE(FAST_ISSUE), .KV_PREP(KV_PREP)) u_me (
        .clk(me_clk), .rst_n(rst_n), .go(me_go), .ready(me_ready), .idle(me_idle),
        .i_nout(me_nout), .i_tiles(me_tiles), .i_k(me_k), .i_wsrc(me_wsrc), .i_wbase(me_wbase),
        .i_ts(me_ts), .i_ks(me_ks), .i_js(me_js), .i_xbase(me_xbase), .i_xks(me_xks), .i_xjs(me_xjs),
        .i_xcs(me_xcs), .i_jsh(me_jsh), .i_split(me_split), .i_wcs(me_wcs), .i_round(me_round), .i_obase(me_obase), .i_ots(me_ots), .i_ojs(me_ojs),
        .i_mmode(me_mmode), .i_oen(me_oen), .i_amax(me_amax), .i_rmax(me_rmax), .i_mbase(me_mbase),
        .mx_we(me_mx_we), .mx_addr(vw_mx_addr), .mx_mask(vw_mx_mask), .mx_data(vw_mx_data),
        .wrom_re(me_wrom_re), .wrom_addr(me_wrom_addr), 
        .scale_re(scale_re), .scale_gre(scale_gre), .scale_addr(scale_addr), .scale_q(scale_q),
        .kv_re(kv_re),
        .x_re(vx_re), .x_addr(vx_addr), .x_q(vx_q),
        .tgo(tgo), .tb(tb), .xl_d(xl_d), .t_lvl(t_lvl), .fab_fault(fab_fault),
        .ov(me_ov), .o_we(me_o_we), .o_addr(vw_me_addr), .o_mask(vw_me_mask), .o_data(vw_me_data),
        .am_idx(am_idx), .am_val(am_val), .am_any(am_any), .progress(me_progress), .fault(me_fault));

    wire       su_active;             // observation (test benches)
    wire [7:0] su_inflight;
    generate if (SU_VEC != 0) begin : g_vsu
    ot_hdc_vstream_rt #(.SW(SW), .LV(LV), .WR(W), .AW(AW), .NW(NW), .KV_FP8(KV_FP8)) u_su (
        .clk(clk), .rt_active(su_active), .rt_inflight(su_inflight), .rst_n(rst_n), .go(su_go), .ready(su_ready), .idle(su_idle),
        .i_nout(su_nout), .i_nin(su_nin),
        .i_asrc((INT8_EMBED != 0) ? 1'b0 : a_src), .i_abase(a_base), .i_aso(a_so), .i_asi(a_si),
        .i_bsrc(b_src), .i_bbase(b_base), .i_bso(b_so), .i_bsi(b_si),
        .i_csrc(c_src), .i_cbase(c_base), .i_cso(c_so), .i_csi(c_si),
        .i_ma(ma), .i_mb(mb), .i_ad(ad), .i_sfu(sfu), .i_mc(mc), .i_md(md),
        .i_dst(dst), .i_dbase(d_base), .i_dso(d_so), .i_dsi(d_si),
        .i_red(red), .i_redsq(redsq), .i_rbase(r_base), .i_rso(r_so), .i_imm1(imm1), .i_imm2(imm2),
        .va_re(su_va_re), .va_addr(su_va_addr), .va_q(su_va_q),
        .vb_re(vb_re), .vb_addr(vb_addr), .vb_q(vb_q),
        .vc_re(vc_re), .vc_addr(vc_addr), .vc_q(vc_q),
        .wrom_re(su_wrom_re), .wrom_addr(su_wrom_addr), .wrom_q(wrom_q[W*16-1:0]),
        .crom_re(crom_re), .crom_addr(crom_addr), .crom_q(crom_q),
        .vm_we(vw_su_we), .vm_waddr(vw_su_addr), .vm_wdata(vw_su_data),
        .kv_we(kv_we), .kv_waddr(kv_waddr), .kv_wdata(kv_wdata),
        .red_we(vw_rd_we), .red_addr(vw_rd_addr), .red_data(vw_rd_data),
        .progress(su_progress), .progress_rows(su_rows), .fault(su_fault));
    end else begin : g_ssu
    ot_hdc_stream #(.W(W), .WR(G * W), .AW(AW), .NW(NW), .KV_FP8(KV_FP8)) u_su (
        .clk(clk), .rst_n(rst_n), .go(su_go), .ready(su_ready), .idle(su_idle),
        .i_nout(su_nout), .i_nin(su_nin),
        .i_asrc((INT8_EMBED != 0) ? 1'b0 : a_src), .i_abase(a_base), .i_aso(a_so), .i_asi(a_si),
        .i_bsrc(b_src), .i_bbase(b_base), .i_bso(b_so), .i_bsi(b_si),
        .i_csrc(c_src), .i_cbase(c_base), .i_cso(c_so), .i_csi(c_si),
        .i_ma(ma), .i_mb(mb), .i_ad(ad), .i_sfu(sfu), .i_mc(mc), .i_md(md),
        .i_dst(dst), .i_dbase(d_base), .i_dso(d_so), .i_dsi(d_si),
        .i_red(red), .i_redsq(redsq), .i_rbase(r_base), .i_rso(r_so), .i_imm1(imm1), .i_imm2(imm2),
        .va_re(su_va_re), .va_addr(su_va_addr), .va_q(su_va_q),
        .vb_re(vb_re), .vb_addr(vb_addr), .vb_q(vb_q),
        .vc_re(vc_re), .vc_addr(vc_addr), .vc_q(vc_q),
        .wrom_re(su_wrom_re), .wrom_addr(su_wrom_addr), .wrom_q(wrom_q),
        .crom_re(crom_re), .crom_addr(crom_addr), .crom_q(crom_q),
        .vm_we(vw_su_we), .vm_waddr(vw_su_addr), .vm_wdata(vw_su_data),
        .kv_we(kv_we), .kv_waddr(kv_waddr), .kv_wdata(kv_wdata),
        .red_we(vw_rd_we), .red_addr(vw_rd_addr), .red_data(vw_rd_data),
        .progress(su_progress), .fault(su_fault));
    assign su_rows = 16'd0;
    assign su_active = u_su.active;
    assign su_inflight = u_su.inflight;
    end endgenerate

    // The embedding read is the only stream use of the weight ROM; a barrier
    // keeps it apart from matrix-vector reads.
    assign wrom_re = ((INT8_WEIGHT != 0) ? 1'b0 : me_wrom_re) |
                     ((INT8_EMBED != 0) ? 1'b0 : su_wrom_re);
    assign int8_wrom_re = (INT8_WEIGHT != 0) ? me_wrom_re : 1'b0;
    assign int8_wrom_addr = me_wrom_addr;
    assign wrom_su = su_wrom_re;
    assign wrom_addr = su_wrom_re ? su_wrom_addr : me_wrom_addr;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) fault <= 1'b0;
        else if (start && st == S_IDLE) fault <= 1'b0;
        else if (me_fault || su_fault || (|embed_faults) || dyn_tiles_bad_instruction) fault <= 1'b1;
    end
endmodule

// a > b on 32-bit unsigned keys, log depth with kept levels (DEC_LA lm_head chunk argmax)
module ot_qwen_core_key_gt (
    input  wire [31:0] a,
    input  wire [31:0] b,
    output wire        gt
);
    (* keep *) wire [7:0] g0, e0;
    (* keep *) wire [3:0] g1, e1;
    (* keep *) wire [1:0] g2, e2;
    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : l0
            assign g0[i] = a[4*i +: 4] > b[4*i +: 4];
            assign e0[i] = a[4*i +: 4] == b[4*i +: 4];
        end
        for (i = 0; i < 4; i = i + 1) begin : l1
            assign g1[i] = g0[2*i+1] | (e0[2*i+1] & g0[2*i]);
            assign e1[i] = e0[2*i+1] & e0[2*i];
        end
        for (i = 0; i < 2; i = i + 1) begin : l2
            assign g2[i] = g1[2*i+1] | (e1[2*i+1] & g1[2*i]);
            assign e2[i] = e1[2*i+1] & e1[2*i];
        end
    endgenerate
    assign gt = g2[1] | (e2[1] & g2[0]);
endmodule

// a >= b on 16-bit unsigned values, log depth with kept levels (DEC_LA chase test)
module ot_qwen_core_ge16 (
    input  wire [15:0] a,
    input  wire [15:0] b,
    output wire        ge
);
    (* keep *) wire [3:0] g0, e0;
    (* keep *) wire [1:0] g1, e1;
    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin : l0
            assign g0[i] = a[4*i +: 4] > b[4*i +: 4];
            assign e0[i] = a[4*i +: 4] == b[4*i +: 4];
        end
        for (i = 0; i < 2; i = i + 1) begin : l1
            assign g1[i] = g0[2*i+1] | (e0[2*i+1] & g0[2*i]);
            assign e1[i] = e0[2*i+1] & e0[2*i];
        end
    endgenerate
    assign ge = g1[1] | (e1[1] & g1[0]) | (e1[1] & e1[0]);
endmodule
